update.foreach:
update user_function

        user_function.open = #{userFunctions.open,jdbcType=INTEGER}

        where user_function.user_id=#{userFunctions.userId,jdbcType=INTEGER} and user_function.function_id = #{userFunctions.functionId,jdbcType=INTEGER}

update mapping

    mapping.begin_location=#{mappings.beginLocation,jdbcType=INTEGER},
    mapping.end_location = #{mappings.endLocation,jdbcType=INTEGER},
    mapping.length = #{mappings.length,jdbcType=INTEGER}

where mapping.id = #{mappings.id,jdbcType=INTEGER}
